import { createElement } from '@wordpress/element';
import { __ } from '@wordpress/i18n';
import { FormWorkspace } from './FormWorkspace';
import { BankAnswerFields } from './BankAnswerFields';
import { ChoiceAnswerFields } from './ChoiceOptionsEditor';
import { getFactoryRuntime } from '../../extensions/LazyFeature';
import { QuestionOptionsBar } from './QuestionOptionsBar';

/** The question form shared by quiz authoring and standalone skill/bank authoring. */
export function QuestionForm({
  question,
  onChange,
  answers,
  settings,
  types,
  onTypeChange,
  ...props
}) {
  const runtime = getFactoryRuntime('questionEditorComponents', 'ChoiceOptionsEditor');
  const choices = ['single-choice', 'multiple-choice'].includes(question.settings?.type);
  const sharedAnswers =
    choices && runtime ? (
      <ChoiceAnswerFields
        options={question.questions || []}
        type={question.settings.type === 'single-choice' ? 'single' : 'multiple'}
        Option={runtime.As}
        ordering={runtime.xs}
        onChange={(questions) => onChange({ questions })}
      />
    ) : (
      <BankAnswerFields
        type={question.settings?.type}
        options={question.questions || []}
        settings={question.settings || {}}
        onChange={onChange}
      />
    );
  return (
    <FormWorkspace
      document={question}
      titleLabel={__('Question title', 'ohmylms')}
      titlePlaceholder={__('Type your question here ...', 'ohmylms')}
      workspaceLabel={__('Question form editor', 'ohmylms')}
      onTitleChange={(name) => onChange({ name })}
      onContentChange={(description) => onChange({ description })}
      previewQuestion={question}
      questionBlockContent={
        <>
          <h3>{__('Answers', 'ohmylms')}</h3>
          {answers || sharedAnswers}
        </>
      }
      {...props}
      flatSettings
      settings={
        <QuestionOptionsBar
          question={question}
          onChange={onChange}
          types={types}
          onTypeChange={onTypeChange}
        />
      }
    />
  );
}
